/**
 * @fileoverview Test the usage of removed methods
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-removed-method-call'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester();
ruleTester.run('no-removed-method-call', rule, {

    valid: [
        // TODO - this is valid ONLY because we have not yet added support for calls like me.getView().addEvents();
        {
            settings: {
                extjs: {
                    fromVersion: '4',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.panel.Panel',
                    initComponent: function(){
                        var me = this;
                        me.getView().addEvents('drop');
                        me.callParent();
                    }
                });
            `
        }
    ],

    invalid: [
        {
            settings: {
                extjs: {
                    fromVersion: '4.2',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.panel.Panel',
                    initComponent: function(){
                        var me = this;
                        me.addEvents('drop');
                        me.callParent();
                    }
                });
            `,
            output: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.panel.Panel',
                    initComponent: function(){
                        var me = this;
                        //me.addEvents('drop');
                        me.callParent();
                    }
                });
            `,
            errors: [
                { message: /Call to removed method 'addEvents' found for 'Ext.panel.Panel'/ }
            ]
        },
        {
            settings: {
                extjs: {
                    fromVersion: '4',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.panel.Panel',
                    initComponent: function(){
                        this.addEvents('drop');
                        this.callParent();
                    }
                });
            `,
            output: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.panel.Panel',
                    initComponent: function(){
                        //this.addEvents('drop');
                        this.callParent();
                    }
                });
            `,
            errors: [
                { message: /Call to removed method 'addEvents' found for 'Ext.panel.Panel'/ }
            ]
        }
    ]
});
